-- 0212_seed_notification_templates.sql
-- REPO/PROD CONVERGENCE — seed the 47 notification_templates config rows.
-- Companion to 0210 (table structure). notification_templates is app-critical config the
-- push/notification system reads at runtime; without this seed a from-scratch replay gets
-- an empty table and templated pushes break. Reconstructed from live prod 2026-07-03.
--
-- IDEMPOTENT: INSERT ... ON CONFLICT (type) DO UPDATE re-applies every run; a no-op on
-- prod (rows already present, identical). updated_by is intentionally NULL (edit-audit
-- metadata; only 2 prod rows had it) and updated_at falls to its default now().

